    ast.Expression,
    ast.BoolOp,
    ast.Compare,
    ast.UnaryOp,
    ast.Constant,
    ast.Name,
    ast.And,
    ast.Or,
    ast.Not,
    ast.Eq,
    ast.NotEq,
    ast.Lt,
    ast.LtE,
    ast.Gt,
    ast.GtE,
}

